3	/// Injectable time source. Every date in the core comes through this, so tests
4	/// can pin "now" and DST edges can be exercised deterministically.
5	public protocol Clock: Sendable {
6	    var now: Date { get }
7	}
8	
9	public struct SystemClock: Clock {
10	    public init() {}
11	    public var now: Date { Date() }
12	}
