14	public final class FixedClock: Clock, @unchecked Sendable {
15	    private let lock = NSLock()
16	    private var _now: Date
17	    public init(_ now: Date) { self._now = now }
18	    public var now: Date {
19	        lock.lock(); defer { lock.unlock() }
20	        return _now
21	    }
22	    public func set(_ date: Date) {
23	        lock.lock(); defer { lock.unlock() }
24	        _now = date
25	    }
26	    public func advance(by interval: TimeInterval) {
27	        lock.lock(); defer { lock.unlock() }
28	        _now = _now.addingTimeInterval(interval)
29	    }
30	}
