3	/// How precisely a time is known.
4	///
5	/// A report that printed only "March 2019" is stored at `.month` and stays
6	/// there. Nothing below the stated precision is ever invented.
7	public enum TimePrecision: String, Codable, Sendable, CaseIterable, Hashable {
8	    case unknown, year, month, day, hour, minute, instant
9	
10	    public var rank: Int {
11	        switch self {
12	        case .unknown: return 0
13	        case .year:    return 1
14	        case .month:   return 2
15	        case .day:     return 3
16	        case .hour:    return 4
17	        case .minute:  return 5
18	        case .instant: return 6
19	        }
20	    }
21	
22	    /// Whether records at this precision may be ordered against each other
23	    /// inside a single day. Coarser records group as time-unknown instead.
24	    public var isOrderableWithinDay: Bool { rank >= TimePrecision.minute.rank }
25	}
26	
27	/// Time-zone context as known at the moment a time was recorded.
28	///
29	/// Both members are optional because a historical paper report frequently
30	/// states neither. An unknown zone is a recorded fact, not a reason to
31	/// substitute the device's current one.
32	public struct ZoneContext: Codable, Sendable, Hashable {
33	    public let offsetMinutes: Int?
34	    public let identifier: String?
35	
36	    public init(offsetMinutes: Int? = nil, identifier: String? = nil) {
37	        self.offsetMinutes = offsetMinutes
38	        self.identifier = identifier
39	    }
40	
41	    public static let unknown = ZoneContext()
42	    public var isKnown: Bool { offsetMinutes != nil || identifier != nil }
43	
44	    public init(_ timeZone: TimeZone, at instant: Date = Date()) {
45	        self.offsetMinutes = timeZone.secondsFromGMT(for: instant) / 60
46	        self.identifier = timeZone.identifier
47	    }
48	}
49	
50	/// A time known only to a stated precision.
51	///
52	/// `text` is an ISO-8601 **prefix**, never padded:
53	/// `"2019"`, `"2019-03"`, `"2019-03-14"`, `"2019-03-14T08:10"`,
54	/// `"2019-03-14T08:10:32Z"`. Because the prefixes sort lexically in
55	/// chronological order, a coarse value sorts at the start of its own span,
56	/// which is where a time-unknown record belongs.
57	public struct PartialDateTime: Codable, Sendable, Hashable, Comparable, CustomStringConvertible {
58	    public let text: String
59	    public let precision: TimePrecision
60	    public let zone: ZoneContext
61	
62	    public init(text: String, precision: TimePrecision, zone: ZoneContext = .unknown) {
63	        self.text = text
64	        self.precision = precision
65	        self.zone = zone
66	    }
67	
68	    public static let unknown = PartialDateTime(text: "", precision: .unknown, zone: .unknown)
69	
70	    /// A fully known instant. The only constructor that produces `.instant`.
71	    public init(instant: Date, zone: ZoneContext) {
72	        let f = ISO8601DateFormatter()
73	        f.formatOptions = [.withInternetDateTime]
74	        if let minutes = zone.offsetMinutes {
75	            f.timeZone = TimeZone(secondsFromGMT: minutes * 60) ?? TimeZone(secondsFromGMT: 0)!
76	        } else {
77	            f.timeZone = TimeZone(secondsFromGMT: 0)!
78	        }
79	        self.text = f.string(from: instant)
80	        self.precision = .instant
81	        self.zone = zone
82	    }
83	
84	    /// Reads a stored value back, deriving precision from its shape.
85	    /// Returns nil for text that is not an ISO-8601 prefix.
86	    public init?(storedText: String, precision: TimePrecision, zone: ZoneContext = .unknown) {
87	        if precision == .unknown {
88	            self.init(text: "", precision: .unknown, zone: zone)
89	            return
90	        }
91	        guard PartialDateTime.shapeMatches(storedText, precision) else { return nil }
92	        self.init(text: storedText, precision: precision, zone: zone)
93	    }
94	
95	    static func shapeMatches(_ s: String, _ p: TimePrecision) -> Bool {
96	        let local = localText(s)
97	        let patterns: [TimePrecision: String] = [
98	            .year: #"[0-9]{4}"#,
99	            .month: #"[0-9]{4}-(0[1-9]|1[0-2])"#,
100	            .day: #"[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])"#,
101	            .hour: #"[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3])"#,
102	            .minute: #"[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]"#,
103	            .instant: #"[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]+)?"#
104	        ]
105	        if p == .unknown { return s.isEmpty }
106	        guard let pattern = patterns[p], local.range(of: "^" + pattern + "$", options: .regularExpression) != nil else { return false }
107	        // Reject calendar rollover (for example February 30).
108	        if p.rank >= TimePrecision.day.rank {
109	            let y = Int(local.prefix(4))!, m = Int(local.dropFirst(5).prefix(2))!, d = Int(local.dropFirst(8).prefix(2))!
110	            var calendar = Calendar(identifier: .gregorian)
111	            calendar.timeZone = TimeZone(secondsFromGMT: 0)!
112	            guard let date = calendar.date(from: DateComponents(year: y, month: m, day: d)),
113	                  calendar.component(.year, from: date) == y,
114	                  calendar.component(.month, from: date) == m,
115	                  calendar.component(.day, from: date) == d else { return false }
116	        }
117	        return true
118	    }
119	
120	    /// The `yyyy-MM-dd` prefix when the value is at least day-precise.
121	    /// Nil for month, year and unknown — those name no single day.
122	    public var datePrefix: String? {
123	        guard precision.rank >= TimePrecision.day.rank, text.count >= 10 else { return nil }
124	        return String(text.prefix(10))
125	    }
126	
127	    public var isKnown: Bool { precision != .unknown }
128	    public var description: String { isKnown ? text : "unknown" }
129	
130	    /// Total order. Unknown sorts last; otherwise chronological by prefix,
131	    /// with coarser precision first when one prefixes the other.
132	    public static func < (a: PartialDateTime, b: PartialDateTime) -> Bool {
133	        switch (a.isKnown, b.isKnown) {
134	        case (false, false): return false
135	        case (false, true):  return false
136	        case (true, false):  return true
137	        case (true, true):
138	            if a.text != b.text { return a.text < b.text }
139	            return a.precision.rank < b.precision.rank
140	        }
141	    }
142	}
