17	/// A half-open query range, built from ISO-8601 prefixes of any precision.
18	public struct DateRange: Sendable, Hashable {
19	    public let start: Date
20	    public let end: Date
21	
22	    /// `from` and `to` are ISO-8601 prefixes: "2019", "2019-03", "2019-03-15",
23	    /// or a full instant. Each is resolved to the first instant of its span.
24	    public init?(from: String, to: String) {
25	        guard let a = PartialDateTime(inferringPrecisionFrom: from)?.span?.start,
26	              let b = PartialDateTime(inferringPrecisionFrom: to)?.span?.start else { return nil }
27	        self.start = a
28	        self.end = b
29	    }
30	
31	    public init(start: Date, end: Date) {
32	        self.start = start
33	        self.end = end
34	    }
35	
36	    /// The bounds as canonical UTC ISO-8601 text.
37	    ///
38	    /// For SQL, where stored instants are UTC strings. Comparing a stored
39	    /// `...Z` value against a caller's `+03:00` text lexically is wrong by the
40	    /// size of the offset; normalising both to UTC first is the fix.
41	    public var utcTextBounds: (start: String, end: String) {
42	        (DateRange.utcFormatter.string(from: start), DateRange.utcFormatter.string(from: end))
43	    }
44	
45	    static let utcFormatter: ISO8601DateFormatter = {
46	        let f = ISO8601DateFormatter()
47	        f.formatOptions = [.withInternetDateTime]
48	        f.timeZone = TimeZone(secondsFromGMT: 0)
49	        return f
50	    }()
51	}
