53	extension PartialDateTime {
54	
55	    /// Builds a value from an ISO-8601 prefix, taking precision from its shape.
56	    public init?(inferringPrecisionFrom text: String) {
57	        guard let precision = PartialDateTime.inferPrecision(text) else { return nil }
58	        self.init(storedText: text, precision: precision)
59	    }
60	
61	    static func inferPrecision(_ s: String) -> TimePrecision? {
62	        let local = PartialDateTime.localText(s)
63	        switch local.count {
64	        case 0: return .unknown
65	        case 4: return .year
66	        case 7: return .month
67	        case 10: return .day
68	        case 13: return .hour
69	        case 16: return .minute
70	        case let n where n >= 19: return .instant
71	        default: return nil
72	        }
73	    }
74	
75	    /// The half-open span of instants this value could denote.
76	    ///
77	    /// Derived for querying only — **nothing here is written back to storage**,
78	    /// so a month-precision record stays `"2019-03"` on disk. This answers
79	    /// "which instants could that label cover", which is a different question
80	    /// from "what time did this happen", and the second is still unknown.
81	    ///
82	    /// Resolved in the record's own offset when it has one, otherwise in UTC.
83	    /// For a coarse value with no offset that means the span can be up to a day
84	    /// out at its edges, which is why such a record reports `.potential` rather
85	    /// than `.definite` near a boundary.
86	    public var span: (start: Date, end: Date)? {
87	        guard isKnown, Self.shapeMatches(text, precision) else { return nil }
88	
89	        if precision == .instant {
90	            let formatter = ISO8601DateFormatter()
91	            formatter.formatOptions = [.withInternetDateTime]
92	            let parsedText: String
93	            if Self.explicitOffset(text) != nil { parsedText = text.uppercased() }
94	            else {
95	                let offset = zone.offsetMinutes ?? 0
96	                let suffix = String(format: "%@%02d:%02d", offset < 0 ? "-" : "+", abs(offset) / 60, abs(offset) % 60)
97	                parsedText = text + suffix
